@@ -694,100 +694,103 @@ message DelegatedPullStarted {

 message BytesProgress {
   // Cumulative values for the delegated transfer so far. Receivers that feed
   // delta-oriented progress renderers must subtract the last observed values.
   uint64 files_completed = 1;
   uint64 files_total = 2;
   uint64 bytes_completed = 3;
   uint64 bytes_total = 4;
 }

 message DelegatedPullSummary {
   // The old per-direction summary shape plus a delegation-specific
   // diagnostic field.
   uint64 files_transferred = 1;
   uint64 bytes_transferred = 2;
   uint64 bytes_zero_copy = 3;
   bool   tcp_fallback_used = 4;
   uint64 entries_deleted = 5;

   // Diagnostic: the data-plane peer address this dst observed when
   // connecting to src. Useful for operator audit logs. Not a proof of
   // byte-path isolation.
   string source_peer_observed = 6;

   // The destination's contained per-file failure report, copied
   // verbatim from the session `TransferSummary` this delegated run's
   // DESTINATION computed (cr-pfc4-1, within contract v6). Identical
   // semantics to `TransferSummary.files_failed` / `failures`:
   // `files_failed` is the exact count, `failures` is the sender-capped
   // named subset (64 entries, capped once at the summary's single
   // construction site), so a shorter list means "capped", never "some
   // failures were forgotten".
   //
   // The delegated topology re-encodes the authoritative session
   // summary into THIS message before it reaches the initiating CLI, so
   // the report has to ride it too: without these fields a delegated
   // remote→remote mirror with contained destination failures reports
   // clean success while the requested files are absent.
   uint64 files_failed = 7;
   repeated FileFailure failures = 8;
   // ssc-6: the exact failed-path set (see TransferSummary.failed_paths),
   // re-encoded verbatim so a delegated initiator can retry precisely.
   repeated string failed_paths = 9;
   bool failed_paths_truncated = 10;
   // cr-rework-1: see TransferSummary.left_in_place, re-encoded verbatim.
   repeated string left_in_place = 11;
   bool left_in_place_truncated = 12;
   // cr-rework-3: see TransferSummary.removed_incomplete, re-encoded verbatim.
   repeated string removed_incomplete = 13;
   bool removed_incomplete_truncated = 14;
+  // Contract 7 (cr-jl4fix2-1): see TransferSummary.left_in_place_raw,
+  // re-encoded verbatim.
+  repeated bytes left_in_place_raw = 15;
 }

 message DelegatedPullError {
   string upstream_message = 1;

   enum Phase {
     UNKNOWN = 0;
     DELEGATION_REJECTED = 1; // gate denied (master switch / allowlist / per-module override)
     CONNECT_SOURCE = 2;      // dst could not reach src
     NEGOTIATE = 3;           // src refused dst (auth/ACL/handshake)
     TRANSFER = 4;            // mid-transfer pull failure
     APPLY = 5;               // dst-side apply failure (containment, disk, perms)
   }
   Phase phase = 2;
 }

 // ─────────────────────────────────────────────────────────────────────
 // GetState — daemon snapshot. See §6.3 of docs/plan/TUI_DESIGN.md.
 // ─────────────────────────────────────────────────────────────────────

 message GetStateRequest {
   // Maximum number of recent[] entries to return. 0 = use the
   // daemon's default (50). Ignored if larger than what the daemon
   // is tracking; the response simply contains all rows the ring
   // currently holds.
   uint32 recent_limit = 1;
 }

 message DaemonState {
   // Daemon's own version (CARGO_PKG_VERSION), e.g. "0.1.0".
   string version = 1;
   // Seconds since the daemon process started serving RPCs.
   uint64 uptime_seconds = 2;
   // Currently-exported modules. Reuses the existing ModuleInfo
   // message so clients that already render ListModules output can
   // reuse the same rendering pipeline.
   repeated ModuleInfo modules = 3;
   // Live transfers — populated from the always-on ActiveJobs table.
   // Not gated on `--metrics`; an operator can always ask the daemon
   // what it's doing right now.
   repeated ActiveTransfer active = 4;
   // Recent completed transfers, oldest-first. Bounded by the
   // daemon's recent-runs ring depth (default 50, configurable via
   // GetStateRequest.recent_limit). Drained when the ring fills.
   repeated TransferRecord recent = 5;
   // Counter snapshot. Reads from the TransferMetrics atomics —
   // when `--metrics` is off the atomics never incremented, so all
   // fields are zero. active[] and recent[] are independent of this
   // and remain populated.
   Counters counters = 6;
@@ -1175,100 +1178,106 @@ message FileFailure {
   // lossy text collides with another's names its own file; empty
   // otherwise, or when they would not fit the path bound.
   bytes raw_relative_path = 3;
 }

 // DESTINATION → SOURCE at close: the end that wrote bytes and
 // executed deletes attests to the outcome (one summary shape for
 // every direction; it replaced the per-direction summaries at cutover).
 message TransferSummary {
   uint64 files_transferred = 1;
   uint64 bytes_transferred = 2;
   uint64 entries_deleted = 3;   // mirror executed destination-local
   bool in_stream_carrier_used = 4;
   uint64 files_resumed = 5;
   // Per-file failures the destination contained instead of faulting the
   // session (contract v6). `files_failed` counts every one; `failures`
   // carries at most MAX_REPORTED_FILE_FAILURES (64) of them — the
   // sender caps the list so a catastrophic run cannot produce an
   // unbounded frame, while the total stays exact.
   uint64 files_failed = 6;
   repeated FileFailure failures = 7;
   // ssc-6 (D-2026-09-28-1/-3): the EXACT set of paths that failed, so
   // the initiator's end-of-run retry passes re-scan precisely those
   // files — `failures` is capped at 64 named entries, which is a
   // report, not a work list. Bounded by encoded bytes
   // (MAX_WIRE_FAILED_PATHS_ENCODED_BYTES); when the set does not fit,
   // `failed_paths_truncated` is true and the initiator falls back to
   // the capped report's paths and says so.
   repeated string failed_paths = 8;
   bool failed_paths_truncated = 9;
   // cr-rework-1 (contract v7, cr-win-1): the subset of `failed_paths`
   // whose failure left this run's own incomplete copy at the destination
   // (a target that could not be removed, or a resume partial of a file
   // that did not exist before). Under --ignore-existing the initiator's
   // retry passes re-send exactly these with that flag off — the copy is
   // not one the user asked to keep — and the set must be exact, not read
   // off the 64-entry `failures` report. Bounded by encoded bytes
   // (MAX_WIRE_LEFT_IN_PLACE_ENCODED_BYTES); `left_in_place_truncated`
   // says the set did not fit, and the initiator then retries none of the
   // paths it cannot classify rather than guess.
   repeated string left_in_place = 10;
   bool left_in_place_truncated = 11;
   // cr-rework-3 (contract v7): the subset of `failed_paths` whose
   // incomplete copy this session positively removed. The initiator keeps
   // a path classified as this run's leftover across retry passes only
   // while its copy is still there; once removed, a file that appears at
   // the path later is protected by --ignore-existing like any other.
   // Bounded like `left_in_place`.
   repeated string removed_incomplete = 12;
   bool removed_incomplete_truncated = 13;
+  // Contract 7 (JOB_LOGS review cr-jl4fix2-1): the left-in-place entries
+  // whose names are not UTF-8, by their exact bytes (`/`-separated);
+  // `left_in_place` then holds only entries named by their text, so two
+  // names that collapse to one text never share the status. Bounded like
+  // `left_in_place`; `left_in_place_truncated` covers both lists.
+  repeated bytes left_in_place_raw = 14;
 }

 // Structured refusal/abort — an end says why before closing.
 message SessionError {
   enum Code {
     SESSION_ERROR_UNSPECIFIED = 0;
     BUILD_MISMATCH = 1;
     MODULE_UNKNOWN = 2;
     READ_ONLY = 3;
     DELEGATION_REFUSED = 4;
     SCAN_INCOMPLETE = 5;
     PROTOCOL_VIOLATION = 6;
     DATA_PLANE_FAILED = 7;
     CANCELLED = 8;
     INTERNAL = 9;
     // otp-10b: the responder's operator disabled checksum hashing
     // (`--no-server-checksums` / `server_checksums_enabled = false`),
     // so a `COMPARISON_MODE_CHECKSUM` open is refused at OPEN — the
     // session never silently degrades a content-compare request to a
     // weaker mode (contract v3).
     CHECKSUM_DISABLED = 10;
   }
   Code code = 1;
   string message = 2;
   // BUILD_MISMATCH: both build ids, so the operator sees exactly
   // which end is stale.
   string local_build_id = 3;
   string peer_build_id = 4;
   // otp-7b-2 (D-2026-07-09-1 Q2 rider): the file the fault concerns,
   // when one is known (a mid-record read/write failure names its
   // file). OPTIONAL for explicit presence (codex 7b-2 G1): the empty
   // string is itself a valid identity — the single-file-root transfer
   // uses relative path "" — so absence must be distinguishable from
   // it. Lets the reporting end's end-of-operation summary name the
   // affected file structurally instead of string-scraping the message.
   optional string relative_path = 5;
 }

 // The single frame type BOTH wire directions carry. Which frames an
 // end may send is determined by ROLE and phase
 // (docs/TRANSFER_SESSION.md frame table — field numbers frozen
 // there). Reuses the engine's existing payload vocabulary verbatim.
 message TransferFrame {
   oneof frame {
     SessionHello hello = 1;
     SessionOpen open = 2;
     SessionAccept accept = 3;
     FileHeader manifest_entry = 4;
     ManifestComplete manifest_complete = 5;
     NeedBatch need_batch = 6;
