 /// A path set in wire form: sorted, bounded by
 /// [`MAX_WIRE_LEFT_IN_PLACE_ENCODED_BYTES`], `(paths, truncated)`.
 fn wire_path_set(set: &std::collections::HashSet<String>) -> (Vec<String>, bool) {
     let mut paths: Vec<&String> = set.iter().collect();
     paths.sort();
     let mut out = Vec::new();
     let mut remaining = MAX_WIRE_LEFT_IN_PLACE_ENCODED_BYTES;
     for path in paths {
         let cost = path.len().saturating_add(4);
         if cost > remaining {
             return (out, true);
         }
         remaining -= cost;
         out.push(path.clone());
     }
     (out, false)
 }

 /// Outcome of writing payload(s) to a sink.
 #[derive(Debug, Default, Clone)]
 pub struct SinkOutcome {
     pub files_written: usize,
     pub bytes_written: u64,
     /// Files that failed on their own while the session continued
     /// (D-2026-07-30-1), capped at [`MAX_REPORTED_FILE_FAILURES`].
     pub failures: Vec<FileFailure>,
     /// Every per-file failure counted, including those past the cap.
     pub files_failed_total: u64,
     /// Exact identity of the paths *this outcome's own payload* failed,
     /// uncapped and separate from the reported list (pfc-3). One payload
     /// is inherently bounded — the planner clamps a shard's member count
     /// to at most 4096 (`count_target.clamp(128, 4096)`,
     /// `transfer_plan.rs`), every other payload shape carries exactly one
     /// file — while the reported list is a session-wide report that has
     /// to stay capped for memory and the wire. Keeping identity here is
     /// what lets a shard that failed more members than the cap still
     /// name its healthy ones as complete.
     /// [`SinkOutcome::merge_failures`] deliberately does not extend it:
     /// the session-wide set has no such bound, and the resulting excess
     /// of `files_failed_total` over this list is exactly the signal
     /// [`SinkOutcome::file_failed`] reads as "identity is incomplete
     /// here, answer conservatively".
     failed_paths: std::collections::HashSet<String>,
     /// cr-rework-1: the exact subset of `failed_paths` whose failure left
     /// this run's own incomplete copy at the destination — recorded from
     /// the reason [`settle_failed_target`] annotates, here at the one
     /// point every failure passes through, so it never depends on the
     /// capped report. Merged like `failed_paths`.
     left_in_place: std::collections::HashSet<String>,
+    /// JOB_LOGS review cr-jl4fix2-1: the same for entries whose names are
+    /// not UTF-8, by their exact bytes — `left_in_place` then holds only
+    /// entries named by their text, so two names that collapse to one text
+    /// never share the status. A write site records a failure by its text;
+    /// [`named_raw`](Self::named_raw) names it from the session's manifest.
+    left_in_place_raw: std::collections::HashSet<Vec<u8>>,
     /// cr-rework-3: the exact set of failed paths whose incomplete copy
     /// this outcome's writes positively removed. The retry loop keeps a
     /// path classified as this run's leftover only while the copy is
     /// still there; once a retry removed it, a file that appears at the
     /// path later is protected by `--ignore-existing` like any other.
     removed_incomplete: std::collections::HashSet<String>,
 }

